"""Conservative first-aid prompts. No medicine doses."""
EN = ["Call 112 now.", "Stay with the person and keep them as comfortable as possible.", "Do not give food, drink, or medicines unless a professional directs you.", "Tell the dispatcher what happened and when symptoms began."]
HI = ["अभी 112 पर कॉल करें।", "व्यक्ति के साथ रहें और उन्हें आरामदायक स्थिति में रखें।", "पेशेवर की सलाह के बिना कुछ खाने-पीने या दवा न दें।", "डिस्पैचर को बताएं कि क्या हुआ और लक्षण कब शुरू हुए।"]
HINGLISH = ["Abhi 112 par call karein.", "Vyakti ke saath rahein aur unhe aaram se rakhein.", "Professional ki salah ke bina khana, paani ya dawa na dein.", "Dispatcher ko batayein kya hua aur symptoms kab shuru hue."]
SPECIAL = {
"snake_bite": (["Keep the person calm and still.", "Immobilise the bitten limb at about heart level.", "Remove rings, watches, and tight clothing.", "Note the time of the bite and get to hospital immediately.", "Do not cut, suck, ice, or apply a tourniquet."], ["व्यक्ति को शांत और स्थिर रखें।", "काटे गए अंग को हृदय के स्तर के आसपास स्थिर रखें।", "अंगूठी, घड़ी और तंग कपड़े हटा दें।", "काटने का समय नोट करें और तुरंत अस्पताल जाएं।", "घाव काटें या चूसें नहीं; बर्फ या कसाव न लगाएं।"], ["Vyakti ko shaant aur sthir rakhein.", "Kaatay ang ko dil ke level ke aas-paas sthir rakhein.", "Anguthi, ghadi aur tight kapde hata dein.", "Bite ka samay note karein aur turant hospital jaayein.", "Zakhm na kaatein, na choosen; ice ya tourniquet na lagayein."]),
"chest_pain": (["Sit upright and rest.", "Loosen tight clothing.", "Ask whether they have their own prescribed emergency medicine.", "Stay with them; do not let them walk or drive."], ["सीधा बैठाकर आराम कराएं।", "तंग कपड़े ढीले करें।", "पूछें कि क्या उनकी अपनी निर्धारित आपातकालीन दवा है।", "साथ रहें; उन्हें चलने या गाड़ी चलाने न दें।"], ["Seedha bithakar aaram karayein.", "Tight kapde dheele karein.", "Poochhein kya unki apni prescribed emergency medicine hai.", "Saath rahein; unhe chalne ya drive karne na dein."]),
"severe_bleeding": (["Press firmly on the wound with clean cloth or gauze.", "Keep steady pressure; add cloth on top if soaked through.", "Do not remove embedded objects.", "Keep the person lying down and warm."], ["साफ कपड़े या गॉज़ से घाव पर जोर से दबाव दें।", "दबाव बनाए रखें; कपड़ा भीग जाए तो ऊपर दूसरा रखें।", "धंसी हुई वस्तु न निकालें।", "व्यक्ति को लिटाकर गर्म रखें।"], ["Saaf kapde ya gauze se zakhm par mazboot dabav dein.", "Dabav banaye rakhein; bheegne par upar aur kapda rakhein.", "Dhansi cheez ko na nikalein.", "Vyakti ko litakar garam rakhein."]),
"minor_bleeding": (["Press firmly on the wound with a clean cloth for 10 minutes.", "Raise the injured limb if possible.", "Do not remove a soaked cloth; place another cloth on top.", "Go to a hospital if the bleeding does not stop."], ["साफ कपड़े से घाव पर 10 मिनट तक जोर से दबाव दें।", "संभव हो तो घायल अंग को ऊपर उठाएं।", "भीगा कपड़ा न हटाएं; उसके ऊपर दूसरा कपड़ा रखें।", "खून न रुके तो अस्पताल जाएं।"], ["Saaf kapde se zakhm par 10 minute mazboot dabav dein.", "Mumkin ho to chot wala haath ya pair upar rakhein.", "Bheega kapda na hataayein; uske upar doosra kapda rakhein.", "Khoon na ruke to hospital jaayein."]),
"seizure": (["Clear nearby hard or sharp objects and protect the head.", "Do not restrain them or put anything in their mouth.", "Time the seizure.", "When jerking stops, place them on their side if breathing."], ["आसपास की कठोर या नुकीली चीजें हटाएं और सिर बचाएं।", "उन्हें पकड़कर न रोकें और मुंह में कुछ न डालें।", "दौरे का समय नोट करें।", "झटके रुकने पर, सांस चल रही हो तो करवट पर लिटाएं।"], ["Paas ki sakht ya nokeeli cheezein hata kar sir bachayein.", "Unhe pakadkar na rokein aur munh mein kuch na daalein.", "Seizure ka samay note karein.", "Jhatke rukne par, saans ho to karwat par litaayein."]),
"severe_burn": (["Cool the burn under clean cool running water for 20 minutes.", "Remove jewellery or clothing near it if not stuck.", "Do not use ice, butter, or ointments.", "Cover loosely with clean non-fluffy material."], ["जले हिस्से को 20 मिनट तक साफ ठंडे बहते पानी से ठंडा करें।", "पास के गहने या कपड़े हटाएं, यदि चिपके न हों।", "बर्फ, मक्खन या मरहम न लगाएं।", "साफ, रोएं-रहित कपड़े से ढीला ढकें।"], ["Jale hisse ko 20 minute thande bahte paani se thanda karein.", "Paas ke gehne ya kapde hataayein agar chipke na hon.", "Ice, butter ya ointment na lagayein.", "Saaf, bina roye wale kapde se dheela dhakein."]),
"stroke_symptoms": (["Use FAST: face, arm, speech, time.", "Note the time symptoms started.", "Keep them safe and still; call 112 immediately.", "Give nothing to eat or drink."], ["FAST देखें: चेहरा, बांह, बोलना, समय।", "लक्षण शुरू होने का समय नोट करें।", "उन्हें सुरक्षित और स्थिर रखें; तुरंत 112 करें।", "खाने या पीने को कुछ न दें।"], ["FAST dekhein: face, arm, speech, time.", "Symptoms shuru hone ka samay note karein.", "Unhe surakshit aur sthir rakhein; turant 112 karein.", "Khaane ya peene ko kuch na dein."]),
"poisoning": (["Do not induce vomiting.", "Keep the container or package for responders.", "Do not give food, drink, or remedies unless told by a professional.", "Tell 112 what was taken and when."], ["उल्टी कराने की कोशिश न करें।", "डिब्बा या पैकेट सहायता दल के लिए रखें।", "पेशेवर के कहे बिना खाना, पेय या घरेलू उपाय न दें।", "112 को बताएं क्या और कब लिया गया।"], ["Ulti karane ki koshish na karein.", "Container ya packet responders ke liye rakhein.", "Professional ke kahe bina khana, drink ya gharelu nuskha na dein.", "112 ko batayein kya aur kab liya gaya."]),
}
SPECIAL["major_trauma"] = (["Do not move the person unless there is immediate danger.", "Keep the head and neck still.", "Press firmly on bleeding with a clean cloth.", "Keep them warm and talking.", "Give no food or water."], ["तुरंत खतरा न हो तो व्यक्ति को न हिलाएं।", "सिर और गर्दन को स्थिर रखें।", "खून बहने पर साफ कपड़े से जोर से दबाव दें।", "उन्हें गर्म रखें और बात करते रहें।", "खाना या पानी न दें।"], ["Turant khatra na ho to vyakti ko na hilaayein.", "Sir aur gardan ko sthir rakhein.", "Khoon behne par saaf kapde se mazboot dabav dein.", "Unhe garam rakhein aur baat karte rahein.", "Khana ya paani na dein."])
def steps(flag: str, language: str):
    lang = (language or "en").lower()
    idx = 1 if lang == "hi" else (2 if lang == "hinglish" else 0)
    base = [EN, HI, HINGLISH][idx]
    if flag in SPECIAL: base = SPECIAL[flag][idx]
    if flag == "minor_bleeding":
        return base
    first = ["Call 112 now.", "अभी 112 पर कॉल करें।", "Abhi 112 par call karein."][idx]
    return [first] + [s for s in base if s != first][:6]
